package com.day18.auth.controller; import com.day18.auth.service.AuthService; import java.util.Map; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/auth") public class AuthController { final AuthService s; public AuthController(AuthService s){this.s=s;} @PostMapping("/register") public ResponseEntity<?> register(@RequestBody Map<String,String> b){s.register(b.get("username"),b.get("password"));return ResponseEntity.status(201).body(Map.of("message","registered"));} @PostMapping("/login") public Map<String,String> login(@RequestBody Map<String,String>b){return s.login(b.get("username"),b.get("password"));} @GetMapping("/health") public Map<String,String> health(){return Map.of("status","UP");} }
